const { useState } = React;

function App() {
  const [page, setPage] = useState("account");

  const user = {
    name: "Priya Shah",
    email: "priya@mail.com",
    avatarKey: "person"
  };

  function handleLogout() {
    setPage("login");
  }

  function handleMyOrders() {
    setPage("orders");
  }

  if (page === "login") {
    return (
      <main style={styles.container}>
        <h1 style={styles.title}>Login</h1>
        <p style={{ fontStyle: "italic", color: "#555" }}>
          This is the Login page placeholder.
        </p>
        <button style={styles.button} onClick={() => setPage("account")}>Go to My Account</button>
      </main>
    );
  }

  if (page === "orders") {
    return (
      <main style={styles.container}>
        <h1 style={styles.title}>Orders</h1>
        <p style={{ fontStyle: "italic", color: "#555" }}>
          This is the Orders page placeholder.
        </p>
        <button style={styles.button} onClick={() => setPage("account")}>Back to My Account</button>
      </main>
    );
  }

  // Account page
  return (
    <main style={styles.container}>
      <h1 style={styles.title}>My Account</h1>

      <section style={styles.card} aria-label="User profile">
        <img
          src={`/runtime/photos/${user.avatarKey}.jpg`}
          alt="User avatar"
          style={styles.avatar}
        />
        <div>
          <p style={styles.userName}>{user.name}</p>
          <p style={styles.userEmail}>{user.email}</p>
        </div>
      </section>

      <nav aria-label="Account navigation" style={styles.nav}>
        <button style={styles.linkButton} onClick={handleMyOrders}>
          My orders
        </button>
        <button style={styles.linkButton} onClick={() => alert('Saved addresses clicked')}>
          Saved addresses
        </button>
        <button style={styles.linkButton} onClick={() => alert('Payment methods clicked')}>
          Payment methods
        </button>
      </nav>

      <hr style={styles.divider} />

      <button style={styles.logoutButton} onClick={handleLogout}>
        Log out
      </button>
    </main>
  );
}

const styles = {
  container: {
    maxWidth: 400,
    margin: "2rem auto",
    fontFamily: "Arial, sans-serif",
    padding: "0 1rem",
    color: "#222"
  },
  title: {
    fontWeight: "normal",
    fontSize: "1.5rem",
    marginBottom: "1rem",
    borderBottom: "1px solid #999",
    paddingBottom: "0.25rem"
  },
  card: {
    display: "flex",
    alignItems: "center",
    border: "1px solid #999",
    borderRadius: 6,
    padding: "0.75rem 1rem",
    marginBottom: "1.5rem",
    gap: "1rem"
  },
  avatar: {
    width: 48,
    height: 48,
    borderRadius: "50%",
    objectFit: "cover",
    border: "1px solid #ccc"
  },
  userName: {
    margin: 0,
    fontWeight: "bold",
    fontSize: "1rem"
  },
  userEmail: {
    margin: 0,
    fontSize: "0.875rem",
    color: "#555"
  },
  nav: {
    display: "flex",
    flexDirection: "column",
    gap: "0.5rem",
    marginBottom: "1.5rem"
  },
  linkButton: {
    background: "none",
